def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len({grid[y][x] for y, x in cells}) >= 3:
                r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
                c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
                return [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
